Reformatting a **spread-based InDesign document with multiple master pages into a single-page format**, **while preserving all original positions, margins, and master page references**, is a common automation challenge. Below is a tailored, **optimized JSX script** for Adobe InDesign. This script will:

- Duplicate all pages as single pages (i.e., all become right-side pages, not spreads).
- Keep each page’s applied master.
- Maintain positions of all page items.
- Preserve original margins and layouts.

**Note:** Due to the way InDesign handles master pages, *single pages* vs *spreads* can sometimes affect how master items flow. This script makes every page a single in a new document, applies the correct master, and replicates the page geometry and content.

---

```javascript
/*
    InDesign Script: Split Spreads into Single Pages while Retaining Masters/Layout

    This script:
    - Duplicates each spread page to a new document as a single page
    - Applies equivalent master pages
    - Preserves all layout, margin, and element positioning
*/

if (app.documents.length === 0) {
    alert("Please open a document first.");
    exit();
}

var sourceDoc = app.activeDocument;
var unitBackup = sourceDoc.viewPreferences.horizontalMeasurementUnits;
sourceDoc.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
sourceDoc.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;

// Create new document with same page size and orientation, single page mode
var newDoc = app.documents.add(false);
newDoc.documentPreferences.facingPages = false;
newDoc.documentPreferences.pageWidth = sourceDoc.documentPreferences.pageWidth;
newDoc.documentPreferences.pageHeight = sourceDoc.documentPreferences.pageHeight;
newDoc.documentPreferences.pagesPerDocument = sourceDoc.pages.length;

// --- COPY MASTER PAGES ---
var masterMap = {};
for (var i = 0; i < sourceDoc.masterSpreads.length; i++) {
    var ms = sourceDoc.masterSpreads[i];
    var label = ms.name;
    // Copy each master to new doc
    var newMS = newDoc.masterSpreads.add();
    newMS.name = label;
    // Copy page geometry and margins for both sides
    for (var j = 0; j < ms.pages.length; j++) {
        var srcMasterPage = ms.pages[j];
        var dstMasterPage = newMS.pages[j];

        // Set margins
        dstMasterPage.marginPreferences.top = srcMasterPage.marginPreferences.top;
        dstMasterPage.marginPreferences.bottom = srcMasterPage.marginPreferences.bottom;
        dstMasterPage.marginPreferences.left = srcMasterPage.marginPreferences.left;
        dstMasterPage.marginPreferences.right = srcMasterPage.marginPreferences.right;
        dstMasterPage.marginPreferences.columnCount = srcMasterPage.marginPreferences.columnCount;
        dstMasterPage.marginPreferences.columnGutter = srcMasterPage.marginPreferences.columnGutter;

        // Copy master page items
        for (var k = 0; k < srcMasterPage.pageItems.length; k++) {
            srcMasterPage.pageItems[k].duplicate(dstMasterPage);
        }
    }
    masterMap[label] = newMS;
}

// Remove default masters
while (newDoc.masterSpreads.length > sourceDoc.masterSpreads.length) {
    newDoc.masterSpreads[0].remove();
}

// --- DUPLICATE EACH SPREAD PAGE AS SINGLE PAGE ---
for (var p = 0; p < sourceDoc.pages.length; p++) {
    var srcPage = sourceDoc.pages[p];
    var newPage = newDoc.pages[p];

    // Set margins, columns, and master page
    var srcMasterName = srcPage.appliedMaster ? srcPage.appliedMaster.name : null;
    if (srcMasterName && masterMap[srcMasterName]) {
        newPage.appliedMaster = masterMap[srcMasterName].pages[0];
    } else {
        // Assign None master if original had none
        newPage.appliedMaster = newDoc.masterSpreads.itemByName("[None]").pages[0];
    }

    newPage.marginPreferences.top = srcPage.marginPreferences.top;
    newPage.marginPreferences.bottom = srcPage.marginPreferences.bottom;
    newPage.marginPreferences.left = srcPage.marginPreferences.left;
    newPage.marginPreferences.right = srcPage.marginPreferences.right;
    newPage.marginPreferences.columnCount = srcPage.marginPreferences.columnCount;
    newPage.marginPreferences.columnGutter = srcPage.marginPreferences.columnGutter;

    // Copy all page items to the new page, preserving position
    for (var pi = 0; pi < srcPage.pageItems.length; pi++) {
        try {
            var item = srcPage.pageItems[pi];
            item.duplicate(newPage);
        } catch (e) {
            // Some items may fail to duplicate if they're locked/etc; skip
        }
    }
}

// Remove any leftover blank pages in newDoc (when template may create > source pages)
for (var r = newDoc.pages.length-1; r >= sourceDoc.pages.length; r--) {
    newDoc.pages[r].remove();
}

alert("Done! Each spread is now a single page with layout, margins, and masters preserved.");

sourceDoc.viewPreferences.horizontalMeasurementUnits = unitBackup;
sourceDoc.viewPreferences.verticalMeasurementUnits = unitBackup;
```

---

### How to use:

1. **Open your spreads document** in InDesign.
2. **Open the Scripts panel** (Window > Utilities > Scripts).
3. **Create a new script**:  
   - Right-click User Scripts > Reveal in Finder/Explorer.  
   - Double-click the new script to run.

### Limitations / Notes:
- *Anchored objects, threading, or interactive elements* may need further handling for 100% fidelity in rare cases.
- The script clones both A and B master page sides, but single pages always use the first page of the master (like a right).
- *If your masters are more complex or rely on spread-based logic*, further tweaking may be needed.

Test with a copy of your file before running on production documents!

Let me know if you need refinement for page numbering, section markers, or have specific master page logic!

